import { ArrowRight, CheckCircle, AlertTriangle } from "lucide-react";
import { GlassPanel } from "../../components/ui/GlassPanel";

interface CashFlowData {
  purchases: number;
  sales: number;
  period: string;
}

export default function CashFlowWatch({ data }: { data: CashFlowData }) {
  if (!data) return null;

  const isHealthy = data.sales >= data.purchases;
  const net = data.sales - data.purchases;

  return (
    <GlassPanel
      className={`p-6 border transition-colors
        ${isHealthy
          ? "bg-emerald-500/5 border-emerald-500/20 hover:border-emerald-500/30"
          : "bg-amber-500/5 border-amber-500/20 hover:border-amber-500/30"}
      `}
    >
      {/* HEADER */}
      <div className="flex items-start gap-4">
        <div
          className={`h-10 w-10 rounded-xl flex items-center justify-center
            ${isHealthy ? "bg-emerald-500/10" : "bg-amber-500/10"}`}
        >
          {isHealthy ? (
            <CheckCircle className="w-5 h-5 text-emerald-600" />
          ) : (
            <AlertTriangle className="w-5 h-5 text-amber-600" />
          )}
        </div>

        <div className="flex-1">
          <h3 className="text-base font-semibold text-foreground">
            Cash Flow
          </h3>

          <p className="text-sm text-muted mt-0.5">
            {isHealthy
              ? `Net positive cash flow ${data.period.toLowerCase()}`
              : `Cash outflow exceeded inflow ${data.period.toLowerCase()}`}
          </p>
        </div>

        <a
          href="/transactions"
          className="text-sm text-primary hover:text-emerald-400 hover:underline flex items-center gap-1 transition-colors"
        >
          View
          <ArrowRight className="w-4 h-4" />
        </a>
      </div>

      {/* AMOUNTS */}
      <div className="mt-4 grid grid-cols-3 gap-4 text-sm">
        <div>
          <p className="text-xs text-muted">Purchases</p>
          <p className="font-semibold text-rose-400">
            ₹{data.purchases.toLocaleString()}
          </p>
        </div>

        <div>
          <p className="text-xs text-muted">Sales</p>
          <p className="font-semibold text-emerald-400">
            ₹{data.sales.toLocaleString()}
          </p>
        </div>

        <div>
          <p className="text-xs text-muted">Net</p>
          <p
            className={`font-semibold ${net >= 0 ? "text-emerald-700" : "text-amber-700"
              }`}
          >
            {net >= 0 ? "+" : "-"}₹{Math.abs(net).toLocaleString()}
          </p>
        </div>
      </div>

      {/* REASSURANCE */}
      {isHealthy && (
        <div className="mt-4 flex items-center gap-2 text-sm text-emerald-400">
          <CheckCircle className="w-4 h-4" />
          Spending is under control and cash inflow is steady.
        </div>
      )}
    </GlassPanel>
  );
}

